"Home" | 
/**  End. */
"End" | 
/**  Page Up. */
"PageUp" | 
/**  Page Down. */
"PageDown" | 
/**
 *  Escape (M-11.3: ends the marking of the Nano search, cancels its
 *  prompt).
 */
"Escape" | 
/**  `[`, for Ctrl/Cmd+Shift+[ (M-08.8: fold). */
"BracketLeft" | 
/**  `]`, for Ctrl/Cmd+Shift+] (M-08.8: expand). */
"BracketRight" | 
/**  A, for Ctrl/Cmd+A (and Nano's Ctrl+A). */
"A" | 
/**  B, for Ctrl/Cmd+B (M-10.2). */
"B" | 
/**  C, for Nano's Ctrl+C. */
"C" | 
/**  E, for Ctrl/Cmd+E (M-10.2) and Nano's Ctrl+E and Alt+E. */
"E" | 
/**  H, for Ctrl/Cmd+Shift+H (M-10.2). */
"H" | 
/**  I, for Ctrl/Cmd+I and Ctrl/Cmd+Shift+I (M-10.2). */
"I" | 
/**  K, for Ctrl/Cmd+K (M-10.2) and Nano's Ctrl+K. */
"K" | 
/**  L, for Ctrl/Cmd+Shift+L (M-10.2). */
"L" | 
/**  O, for Nano's Ctrl+O. */
"O" | 
/**  Q, for Ctrl/Cmd+Shift+Q (M-10.2). */
"Q" | 
/**  R, for Vim's Ctrl+R in the facade (M-11.2). */
"R" | 
/**  S, for Nano's Ctrl+S. */
"S" | 
/**  T, for Ctrl/Cmd+Shift+T (M-10.2). */
"T" | 
/**  U, for Nano's Ctrl+U and Alt+U. */
"U" | 
/**  W, for Nano's Ctrl+W. */
"W" | 
/**  X, for Nano's Ctrl+X. */
"X" | 
/**  Y, for Ctrl/Cmd+Y. */
"Y" | 
/**  Z, for Ctrl/Cmd+Z and Ctrl/Cmd+Shift+Z. */
"Z";

/**
 *  FR-026, M-11.4: the left part of the editor's status line with the Vim
 *  or Nano keys: the badge, what is typed but not done, and the commands,
 *  the most important first (the window leaves out from the end what does
 *  not fit).
 */
export type KeysStatusView = {
	/**  "VIM" or "NANO". */
	keymap: string,
	/**  The Vim mode, such as "NORMAL" or "VISUAL LINE"; `None` for Nano. */
	mode: string | null,
	/**
	 *  Which of the palette's mode colours the badge has: 0 normal (and
	 *  Nano), 1 insert, 2 visual, 3 command (`PaletteView::mode_colors`).
	 */
	color: number,
	/**  What is typed but not done yet, or the Nano search prompt. */
	pending: string,
	/**  The commands. */
	hints: KeyHintView[],
	/**  The Nano search prompt is open and takes every key. */
	prompting: boolean,
};

/**
 *  UC-004 A2 to A4, M-07.3: what following a link asks of the window. The
 *  status bar says what else happened (a heading not found, a file that
 *  does not exist, a link leading outside the workspace).
 */
export type LinkAnswer = 
/**  Nothing more for the window. */
{ kind: "done" } | 
/**
 *  A2: the tab of `note`, active now, puts its cursor at the heading
 *  the link names and shows it there.
 */
{ kind: "jump"; 
/**  The note whose tab jumps. */
note: string; 
/**  The revision of the backend's text `offset` is in. */
rev: number; 
/**  Where the heading's text starts, in web units. */
offset: number } | 
/**
 *  A4: the first web address of the session: "Open web address" asks
 *  whether to open it (`link_open_web`).
 */
{ kind: "askWeb"; 
/**  The address, as the link has it. */
address: string } | 
/**
 *  A3: the linked note does not exist; "New note" offers to create
 *  it with its folder and title filled in.
 */
{ kind: "newNote"; 
/**  The folder of the link, `""` for the top folder. */
folder: string; 
/**  The title of the link. */
title: string; 
/**  The default format of new notes, preselected (UC-003 step 2). */
format: FormatName; 
/**  "{title} does not exist yet. Create it?" */
problem: string };

/**
 *  ADR-025: the backend's text of an open note as the window's editor core
 *  starts from it (`ed_mirror`): the text with its line breaks as they are,
 *  its revision, and the cursor the tab opened with.
 */
export type MirrorView = {
	/**  The note, by its id. */
	note: string,
	/**  The revision of the text. */
	rev: number,
	/**  The whole text, its line breaks as the file has them. */
	text: string,
	/**  "Markdown" or "AsciiDoc". */
	format: string,
	/**  The other end of the selection, in web units. */
	anchor: number,
	/**  The cursor, in web units. */
	head: number,
};

/**  UC-003 steps 2–3: what the user entered in "New note". */
export type NewNoteRequest = {
	/**  "Title:". */
	title: string,
	/**  "Folder (empty for the top folder, new folders are created):". */
	folder: string,
	/**  "Note format:". */
	format: FormatName,
};

/**
 *  UC-003 step 2: what the dialog "New note" starts with: the folder of the
 *  active note and the default format of the workspace.
 */
export type NewNoteStart = {
	/**  The folder of the active note, `""` for the top folder. */
	folder: string,
	/**  The default format of new notes (UC-001 BR-001). */
	format: FormatName,
};

/**  What the user chose in the Create dialog (UC-001 steps 1–4, A3). */
export type NewWorkspaceRequest = {
	/**  The directory, as the Options stage named it. */
	directory: string,
	/**  The default format of new notes. */
	format: FormatName,
	/**  "Create as git repository". */
	git: boolean,
	/**  The address of the git remote; empty for none. Only used with `git`. */
	remote: string,
};

/**  M-16.2, UC-004 BR-010: the properties of a stored note. */
export type NotePropertiesView = {
	/**  "Place": the place in the workspace, such as `guide/Install.adoc`. */
	place: string,
	/**  "Format": "Markdown" or "AsciiDoc". */
	format: string,
	/**  "Size", such as `2 KB`. */
	size: string,
	/**  "Last change", local time to the minute. */
	lastChange: string,
};

/**  The answer to choosing a directory to open (UC-002 step 4). */
export type OpenAnswer = 
/**
 *  The dialog closes: the workspace is open now, was open already (A9),
 *  or there was nothing to open; a failure is in the status.
 */
{ kind: "done" } | 
/**  The dialog shows what stands in the way (A3, A5, A7, A11). */
{ kind: "problem"; 
/**  The text of the path field. */
path: string; 
/**  Why the directory cannot be opened, as the egui app says it. */
problem: string; 
/**  What the dialog offers instead. */
offer: OpenOffer | null; 
/**  The recently opened workspaces, without one that is gone (A3). */
recent: string[] };

/**
 *  What the Open dialog offers besides choosing another directory
 *  (M-21.1).
 */
export type OpenOffer = 
/**  UC-002 A3, A4: "Create a new workspace there". */
{ kind: "create"; 
/**  The directory that does not exist. */
directory: string } | 
/**  UC-002 A5, A6: "Open {outer}" and "Open {inner} anyway". */
{ kind: "outer"; 
/**  The workspace the directory lies in. */
outer: string; 
/**  The chosen directory. */
inner: string };

/**  M-05.2: the note overview changed. */
export type OverviewEvent = OverviewItem[];

/**  One line of the note overview (M-05.2, UC-002 BR-008). */
export type OverviewItem = {
	/**
	 *  The note, by its id (`guide/Getting-Started`), which the window sends
	 *  back to open it.
	 */
	note: string,
	/**  The title, with the folder when the title occurs more than once. */
	label: string,
};

/**
 *  The palette of one theme, as `#rrggbb` strings.
 * 
 *  The fields are those of `underline_facade::themes::Palette`, one to one,
 *  followed by the colours the egui app derives from them (`visuals()` and
 *  the editor), so the window computes no colour of its own.
 */
export type PaletteView = {
	/**  The theme's name, such as "Solarized Dark". */
	theme: string,
	/**  Whether the theme is dark; sets the window's `color-scheme`. */
	dark: boolean,
	/**  The background of notes and of text fields. */
	background: string,
	/**  The background of the panels: top bar, menus, status bar. */
	panel: string,
	/**  Body text. */
	foreground: string,
	/**  Weaker text such as markers and hints. */
	weak: string,
	/**  Links. */
	link: string,
	/**  The selection in the editor, drawn half transparent over the text. */
	selection: string,
	/**  The background of code and markup blocks. */
	codeBackground: string,
	/**  Highlighting (ADR-010): comments. */
	comment: string,
	/**  Highlighting: keywords. */
	keyword: string,
	/**  Highlighting: strings. */
	string: string,
	/**  Highlighting: numbers. */
	number: string,
	/**  Highlighting: types. */
	kind: string,
	/**  Highlighting: functions. */
	function: string,
	/**  Highlighting: variables. */
	variable: string,
	/**  Highlighting: headings. */
	heading: string,
	/**  The fill of a switched-on toggle or a chosen entry (`Palette::chosen`). */
	chosen: string,
	/**  The text on [`PaletteView::chosen`] (`Palette::chosen_text`). */
	chosenText: string,
	/**  The fill of a button that is not switched on (`Palette::button`). */
	button: string,
	/**  Search hits (`Palette::found`, UC-008 BR-008). */
	found: string,
	/**  The fill behind a search hit in the text (`Palette::found_background`). */
	foundBackground: string,
	/**  The fill of a box set into the panel (`Palette::inset`). */
	inset: string,
	/**
	 *  The input modes in the editor's status line, as normal, insert,
	 *  visual and command (`Palette::mode_colors`, FR-026).
	 */
	modeColors: string[],
	/**  The text on each of [`PaletteView::mode_colors`] (`Palette::text_on`). */
	modeText: string[],
	/**
	 *  M-09.2: bold text and headings in the facade, egui's
	 *  `strong_text_color()` of the theme's base look: white on a dark
	 *  theme, black on a light one.
	 */
	strong: string,
};

/**
 *  The operating system the app runs on.
 * 
 *  The window needs it to name the command key in shortcut texts ("Cmd" on
 *  macOS, "Ctrl" elsewhere).
 */
export type Platform = 
/**  macOS. */
"macos" | 
/**  Windows. */
"windows" | 
/**  Linux and every other system, which use the same shortcut texts. */
"linux";

/**  M-16.2: the properties of the active tab's note; `null` without one. */
export type PropertiesEvent = TabPropertiesView | null;

/**
 *  ADR-025: what the backend's answer did in the window's editor core: the
 *  patch for the source view (the backend's changes moved over the
 *  window's own edits), or that the copies went apart and the window sends
 *  its whole text.
 */
export type RemoteApplied = {
	/**  The patch for the source view; `None` when nothing changed. */
	patch: EditorPatch | null,
	/**  The copies went apart: the window sends its whole text (`ed_resync`). */
	desync: boolean,
	/**  Why they went apart, for the log. */
	reason: string | null,
};

/**  A change of the backend. */
export type RemoteChange = 
/**
 *  Edits one after the other; `sealed` makes them an undo step of their
 *  own (an agent's change, UC-019 BR-007).
 */
{ kind: "edits"; 
/**  The edits. */
edits: SyncEdit[]; 
/**  Whether they are an undo step of their own. */
sealed: boolean } | 
/**  The text is replaced, as after a change from outside (UC-004 A7). */
{ kind: "reload"; 
/**  The new text. */
text: string };

/**  A change of the backend with its revision. */
export type RemoteOp = {
	/**  The revision the change made. */
	rev: number,
	/**  The change. */
	change: RemoteChange,
};

/**  The answer to "Rename" (UC-006 steps 4–7). */
export type RenameAnswer = 
/**
 *  The dialog closes; nothing changed (A4), or the status says why the
 *  note could not be renamed (A5).
 */
{ kind: "done" } | 
/**
 *  Step 7: the note `from` is `to` now; its tab shows it under the new
 *  name, so the window's editor core of `from` goes on as `to`.
 */
{ kind: "renamed"; 
/**  The note before. */
from: string; 
/**  The note now. */
to: string } | 
/**  The dialog stays with what the user entered and says why (A1–A3). */
{ kind: "problem"; 
/**  Why, as the egui app says it. */
problem: string };

/**  UC-006 step 2: what the dialog "Rename note" starts with. */
export type RenameStart = {
	/**  The note to rename. */
	note: string,
	/**  Its title, selected when the dialog shows. */
	title: string,
	/**  Its folder, `""` for the top folder. */
	folder: string,
	/**  BR-009: it is the Home note, the start page of a GitHub wiki. */
	home: boolean,
};

/**  The answer to restoring a deleted note (UC-007 A4–A6). */
export type RestoreAnswer = 
/**  Nothing was restored; the status says why, if anything happened. */
{ kind: "done" } | 
/**  "Restored {t}": the note is back, as `note`. */
{ kind: "restored"; 
/**  The restored note. */
note: string } | 
/**
 *  A6: its place is taken; "Restore note" asks for another title or
 *  folder, or again after a problem.
 */
{ kind: "ask"; 
/**  "Title:". */
title: string; 
/**  "Folder (empty for the top folder, new folders are created):". */
folder: string; 
/**  Why, as the egui app says it. */
problem: string };

/**
 *  M-09.13: where the cursor goes one row up or down, or to the start or
 *  the end of its row, as the window lays the cursor's block out; web
 *  offsets. `up` and `down` are `None` on the first and the last row of the
 *  block, where the cursor goes into the block before or after.
 */
export type RowsView = {
	/**  The cursor the rows were measured at. */
	at: number,
	/**  One row up in the same block. */
	up: number | null,
	/**  One row down in the same block. */
	down: number | null,
	/**  The start of the cursor's row. */
	start: number,
	/**  The end of the cursor's row. */
	end: number,
};

/**  A run of text in one style (M-09.2). */
export type RunView = {
	/**  The text shown, with its line breaks normalised. */
	text: string,
	/**  Bold, in the colour "strong". */
	bold: boolean,
	/**  Italic. */
	italic: boolean,
	/**  Struck through. */
	strike: boolean,
	/**  Inline code, on the code background. */
	code: boolean,
	/**  The address of the link the text belongs to (M-07.4). */
	link: string | null,
	/**
	 *  Where the characters stand in the markup: pairs of a UTF-16 offset in
	 *  `text` and the web offset, relative to the start of the block, of the
	 *  markup character it shows. The characters between two pairs follow one
	 *  another in the markup; the first pair is at 0 unless `text` is empty.
	 */
	offsets: ([number, number])[],
	/**
	 *  The web offset right after the run, relative to the start of the
	 *  block.
	 */
	end: number,
};

/**
 *  M-13.1, UC-008 step 2: the text or the result of the workspace search
 *  changed.
 */
export type SearchEvent = SearchView;

/**
 *  UC-008 step 4: the found note is open; the word found to select, in
 *  web units of the backend's text of `rev`.
 */
export type SearchOpened = {
	/**  The note. */
	note: string,
	/**  The backend's revision of its text. */
	rev: number,
	/**  The start of the word. */
	anchor: number,
	/**  Its end, where the cursor goes. */
	head: number,
};

/**  UC-008 step 2, A4: one result of the search. */
export type SearchResultView = {
	/**
	 *  The number of this result in the session; the window asks for more
	 *  of its notes by it (`search_page`).
	 */
	serial: number,
	/**  What it was searched for. */
	text: string,
	/**  How many notes were found. */
	total: number,
	/**
	 *  The first [`SearchResultView::PAGE`] found notes, title and folder
	 *  matches first (BR-003).
	 */
	notes: FoundNoteView[],
	/**  A4: "{n} note(s) could not be searched.", when some could not. */
	unreadable: string | null,
};

/**
 *  UC-008 step 2, A1: the search of the overlay. Sent as the event
 *  `search` when its text or its result changed.
 */
export type SearchView = {
	/**
	 *  The text searched for, without the spaces around it; empty when
	 *  nothing is searched.
	 */
	text: string,
	/**
	 *  The newest result that fits a text searched for; `None` until the
	 *  first came ("Searching…"). While a new text is searched, the result
	 *  of the text before stays (egui).
	 */
	result: SearchResultView | null,
};

/**
 *  M-08.8, UC-004 BR-012: one section of the note, as the source view folds
 *  it: lines counted from 0.
 */
export type SectionView = {
	/**  The line of the heading. */
	line: number,
	/**
	 *  The last line folding hides; `line` when the section has nothing to
	 *  fold.
	 */
	last: number,
	/**  The section is folded. */
	folded: boolean,
};

/**
 *  M-08.8, M-12.2: the sections of the note shown, sent after the input
 *  that changed them (ADR-024), and when a section was folded or expanded.
 */
export type SectionsView = {
	/**  The note. */
	note: string,
	/**  The revision of the text the sections are of. */
	rev: number,
	/**  The sections, in order. */
	sections: SectionView[],
};

/**  FR-031, BR-011: a selection copy on select puts on the clipboard. */
export type SelectionCopy = {
	/**  The selected markup. */
	text: string,
	/**  The facade's selection as HTML; `None` in the source view. */
	html: string | null,
	/**
	 *  The first copy since the selection was made: the backend keeps what
	 *  the clipboard held before, for pasting over the selection.
	 */
	first: boolean,
};

/**  One setting of UC-010 BR-001, named as in the settings file. */
export type SettingName = "default_format" | "theme" | "input_mode" | "show_line_numbers" | "line_number_side" | "show_minimap" | "copy_on_select" | "git_sync_interval" | "agent_access" | "overview_width" | "tool_panel_width" | "show_menu_bar" | "blink_found_in_minimap";

/**
 *  UC-010, M-01.6: the settings in effect changed, with the palette of the
 *  theme.
 */
export type SettingsEvent = SettingsView;

/**
 *  The settings in effect as the window shows them (UC-010 BR-002), with
 *  the palette of the theme in effect (M-01.6). Choices are given by the
 *  names the settings file and the window use, such as "GitHub Light".
 */
export type SettingsView = {
	/**  The theme in effect (FR-022), by its name. */
	theme: string,
	/**  The colours of the theme in effect. */
	palette: PaletteView,
	/**  The keys the editor follows (FR-024, FR-025): "Normal", "Vim", "Nano". */
	inputMode: string,
	/**  Line numbers in the source view (FR-029). */
	showLineNumbers: boolean,
	/**  "Left" or "Right". */
	lineNumberSide: string,
	/**  The minimap beside the editor. */
	showMinimap: boolean,
	/**  Copying the selection as it is made. */
	copyOnSelect: boolean,
	/**  Minutes between two git syncs. */
	gitSyncInterval: number,
	/**
	 *  What agents may do (UC-017 BR-002): "Off", "Read only",
	 *  "Read and write".
	 */
	agentAccess: string,
	/**  The workspace lowers agent access below the user's level (UC-017 A1). */
	agentAccessLowered: boolean,
	/**
	 *  The workspace asks for more agent access, which is not followed
	 *  (UC-010 BR-008).
	 */
	agentAccessRefused: boolean,
	/**  Width of the note overview in pixels. */
	overviewWidth: number,
	/**  Width of the tool panel in pixels. */
	toolPanelWidth: number,
	/**  Whether the menu bar is shown (M-03.1). */
	showMenuBar: boolean,
	/**  Whether search hits blink in the minimap (UC-008 BR-008). */
	blinkFoundInMinimap: boolean,
	/**
	 *  Q-03: grows each time a settings file was read again; the window
	 *  then sets the panels back to `overview_width` and `tool_panel_width`.
	 */
	widthGeneration: number,
};

/**  How one kind of highlighted text looks (ADR-010). */
export type SpanStyle = {
	/**  The colour, `#rrggbb`. */
	color: string,
	/**  Bold. */
	bold: boolean,
	/**  Italic. */
	italic: boolean,
};

/**  What the window needs to know when it starts (M-01). */
export type StartInfo = {
	/**
	 *  The workspace folder given on the command line (M-01.1), as a display
	 *  string only. The backend opens the workspace from its own stored path,
	 *  never from this string sent back.
	 */
	givenDir: string | null,
	/**  The workspace opened most recently (M-22.1), as a display string. */
	lastWorkspace: string | null,
	/**
	 *  The known workspaces, the most recently opened first (M-22.1), as
	 *  display strings.
	 */
	recentWorkspaces: string[],
	/**  The operating system, for the shortcut texts. */
	platform: Platform,
	/**  The settings in effect with the palette of the theme (M-01.6). */
	settings: SettingsView,
	/**  The names of all themes, in the order of the Theme menu (M-03.6). */
	themes: string[],
	/**
	 *  The status message at start, such as a note about the state file
	 *  (M-01.3).
	 */
	status: string,
	/**  M-10.2: the buttons of the formatting toolbar. */
	tools: ToolView[],
	/**  M-11.4: the input modes of the "Keys" choice, by name. */
	inputModes: string[],
};

/**
 *  What `ws_start` did (M-01.1): the answer, and the workspace part of the
 *  window afterwards.
 */
export type StartOpened = {
	/**  `Problem` shows the Open dialog, as the egui app does at start. */
	answer: OpenAnswer,
	/**  The workspace, overview and tabs after opening. */
	snapshot: WorkspaceSnapshot,
};

/**  M-04.7: the status message changed. */
export type StatusEvent = StatusView;

/**
 *  What the status bar offers beside the status message, while it shows
 *  the report the offer belongs to (M-04.7).
 */
export type StatusOffer = 
/**
 *  UC-007 A4, M-14.3: "Undo" right after deleting a note
 *  (`note_undo_delete`).
 */
"undoDelete";

/**  The status message of the status bar (M-04.7). */
export type StatusView = {
	/**  The text, as the egui app shows it; empty when there is none. */
	text: string,
	/**
	 *  What the status bar offers beside the text, such as "Undo" after
	 *  deleting a note (UC-007 A4); it belongs to this text.
	 */
	offer: StatusOffer | null,
};

/**  The backend's answer to `ed_sync` and `ed_resync`. */
export type SyncAnswer = {
	/**  The revision of the backend's text now. */
	rev: number,
	/**  The hash of that text (FNV-1a, 16 hex digits). */
	hash: string,
	/**  The backend's changes the window has not had, in order. */
	remote: RemoteOp[],
	/**  The window must send its whole text (`ed_resync`). */
	resync: boolean,
};

/**
 *  The window's edits since revision `base`, sent after the frame
 *  (`ed_sync`); none to fetch the backend's changes.
 */
export type SyncBatch = {
	/**  The revision the edits were made on. */
	base: number,
	/**  The edits, one after the other. */
	edits: SyncEdit[],
	/**
	 *  The batch's number; one sent again after its answer was lost is taken
	 *  in once.
	 */
	seq: number,
};

/**
 *  One edit: at char `at`, `remove` chars are replaced by `insert`. The
 *  edits of a list apply one after the other.
 */
export type SyncEdit = {
	/**  Where the edit starts, in chars. */
	at: number,
	/**  How many chars it removes. */
	remove: number,
	/**  What it puts in their place. */
	insert: string,
};

/**  M-16.2: the properties section of the tool panel for the active tab. */
export type TabPropertiesView = {
	/**  The note of the active tab. */
	note: string,
	/**  `None` when the file cannot be read: "Not saved yet". */
	properties: NotePropertiesView | null,
};

/**  One tab of the tab bar (M-06.1). */
export type TabView = {
	/**  The note the tab shows, by its id. */
	note: string,
	/**  The note's title, without marks. */
	title: string,
	/**
	 *  The title, marked " ⚠" when the last save failed, else " •" with
	 *  changes not stored, and " (deleted)" when the note was deleted
	 *  outside.
	 */
	label: string,
	/**  The note's file, shown when the pointer rests on the tab. */
	path: string,
	/**  The editing view of the tab (M-06.7). */
	view: EditingViewName,
	/**
	 *  M-10.8: why the last save failed, for the line above the editor
	 *  "Not stored: {err}. Underline keeps trying."; `None` when it did not.
	 */
	saveError: string | null,
};

/**
 *  M-08.8, M-12.2, ADR-025: what the webview's editor tells its view after
 *  the inputs (`views`); each only once it changed.
 */
export type TabViews = {
	/**  The sections for the fold arrows. */
	sections: SectionsView | null,
	/**  The marked hits: the words of the searches and of the Nano search. */
	found: FoundView | null,
};

/**  A table (M-09.5): its rows of cells, each cell its styled runs. */
export type TableView = {
	/**  The first row is the header: bold and shaded. */
	header: boolean,
	/**  The alignment of each column. */
	align: CellAlignName[],
	/**  The rows, each a list of cells, each a list of runs. */
	rows: RunView[][][],
	/**
	 *  "Table n. {title}" above the table, for an AsciiDoc table with a
	 *  title.
	 */
	caption: string | null,
};

/**  M-06: the tab bar changed. */
export type TabsEvent = TabsView;

/**  The tab bar (M-06): the note tabs left to right and the active one. */
export type TabsView = {
	/**  The note tabs, left to right. */
	tabs: TabView[],
	/**
	 *  The note of the active note tab; `None` without tabs. The note
	 *  overview marks it even while the tab "Todos" is the active one; the
	 *  tab bar then marks the tab "Todos" instead.
	 */
	active: string | null,
	/**  The tab "Todos"; its list comes with feature F15. */
	todoList: TodoTabView,
};

/**
 *  One change of the text: the UTF-16 range `from..to` of the text before it
 *  was replaced by `insert`. The window sends such changes too, for the
 *  edits its own Vim keys make (`apply`, A-01).
 */
export type TextChange = {
	/**  Where the replaced text starts. */
	from: number,
	/**  Where the replaced text ends. */
	to: number,
	/**  The text put in its place. */
	insert: string,
};

/**  The tab "Todos" (M-06.5, UC-021 BR-005), as it is remembered. */
export type TodoTabView = {
	/**  The tab is open. */
	open: boolean,
	/**  The tab is the active one; no note tab is then. */
	active: boolean,
};

/**  M-10.2, FR-023: a function of the formatting toolbar. */
export type ToolName = 
/**  Heading. */
"heading" | 
/**  Bold. */
"bold" | 
/**  Italic. */
"italic" | 
/**  Code. */
"code" | 
/**  List. */
"list" | 
/**  Quote. */
"quote" | 
/**  Link: asks for a web address or a note first. */
"link" | 
/**  Image: asks for an image file first. */
"image" | 
/**  Table. */
"table";

/**  M-10.2: one button of the formatting toolbar, as the egui app labels it. */
export type ToolView = {
	/**  The function. */
	tool: ToolName,
	/**  The label of the button, such as "B" or "List". */
	label: string,
	/**  The hint shown on hover, with the key, such as "Bold (Ctrl+B)". */
	hint: string,
};

/**
 *  A failure of a command, shown to the user.
 * 
 *  `message` is the status text the egui app shows for the same failure, so
 *  the messages stay the same after the migration.
 */
export type UiError = {
	/**  What kind of failure this is. */
	kind: UiErrorKind,
	/**  The text shown to the user. */
	message: string,
};

/**
 *  What kind of failure a [`UiError`] reports, so the window can react to it
 *  without parsing the message.
 * 
 *  The kinds grow with the ported features.
 */
export type UiErrorKind = 
/**  Reading or writing a file or folder failed. */
"io" | 
/**
 *  The window asked for something that does not fit the session's state,
 *  for example a tab that is no longer open.
 */
"invalid" | 
/**  A failure the user cannot act on. */
"internal";

/**
 *  A-01: one change the window's Vim keys made, like [`TextChange`], and
 *  whether it starts a new undo step: the window marks the start of each
 *  Vim command and of each insert session (M-10.1).
 */
export type VimChange = {
	/**  Where the replaced text starts, in UTF-16 units. */
	from: number,
	/**  Where the replaced text ends. */
	to: number,
	/**  The text put in its place. */
	insert: string,
	/**  It is not undone together with the change before it. */
	newStep: boolean,
};

/**  FR-026: a mode of the Vim keys, as the window's Vim keys report it. */
export type VimModeName = 
/**  NORMAL. */
"normal" | 
/**  INSERT. */
"insert" | 
/**  VISUAL. */
"visual" | 
/**  VISUAL LINE. */
"visualLine" | 
/**  COMMAND: a command line after `:` or `/`. */
"command";

/**
 *  FR-026, A-01: what the window's Vim keys (`codemirror-vim`) are doing,
 *  for the status line.
 */
export type VimState = {
	/**  The mode. */
	mode: VimModeName,
	/**  What is typed but not done yet, such as `2d` or `"+`. */
	pending: string,
	/**  The hits of a search are marked (UC-008 BR-008). */
	marked: boolean,
};

/**  M-21.3, M-03.3, M-04.7: a workspace was opened; `null` while none is. */
export type WorkspaceEvent = WorkspaceView | null;

/**
 *  The workspace part of the window at once: what `ws_start` returns, so
 *  the window leaves its loading state with everything in place.
 */
export type WorkspaceSnapshot = {
	/**  The open workspace, if any. */
	workspace: WorkspaceView | null,
	/**  The note overview. */
	overview: OverviewItem[],
	/**  The tab bar. */
	tabs: TabsView,
};

/**  The open workspace as the window names it (M-03.3, M-04.7). */
export type WorkspaceView = {
	/**  The workspace's directory, as the status bar shows it. */
	root: string,
	/**  The folder name, which the top bar shows without the menu bar. */
	name: string,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

type EventEmitTo<T> = [T] extends [null] ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void> : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>;

function makeEvent<TListen, TEmit = TListen>(name: string, serialize?: (payload: TEmit) => unknown, deserialize?: (payload: any) => TListen) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<TListen>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: TEmit) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => __TAURI_EVENT.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => target.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    });

    return Object.assign(fn, base);
}

